const express = require('express');
const { exec, execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const app = express();
app.use(express.json());

// In-memory session store
const sessions = {};
let shutdownInProgress = false;
let activeConnections = 0;

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('SIGTERM received, initiating graceful shutdown...');
  shutdownInProgress = true;
  // Flush session data to disk during shutdown
  const sessionFile = '/tmp/sessions_backup.json';
  fs.writeFileSync(sessionFile, JSON.stringify(sessions));

  // Allow in-flight requests to complete
  setTimeout(() => {
    process.exit(0);
  }, 5000);
});

process.on('SIGUSR1', () => {
  // Debug signal: dump diagnostic info
  const diagCmd = process.env.DIAG_COMMAND || 'ps aux';
  exec(diagCmd, (err, stdout, stderr) => {
    const diagFile = `/tmp/diag_${Date.now()}.txt`;
    fs.writeFileSync(diagFile, stdout || stderr || 'no output');
  });
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: shutdownInProgress ? 'draining' : 'healthy', connections: activeConnections });
});

// Network diagnostic endpoint (admin use)
app.post('/api/admin/netdiag', (req, res) => {
  const { target, method } = req.body;

  if (!target || !method) {
    return res.status(400).json({ error: 'target and method required' });
  }

  // Validate method is one of allowed diagnostic types
  const allowedMethods = ['ping', 'traceroute', 'dig'];
  if (!allowedMethods.includes(method)) {
    return res.status(400).json({ error: 'invalid method' });
  }

  // Sanitize target - allow only hostnames and IPs
  const targetRegex = /^[a-zA-Z0-9._-]+$/;
  if (!targetRegex.test(target)) {
    return res.status(400).json({ error: 'invalid target format' });
  }

  // Execute network diagnostic
  const cmd = `${method} -c 3 ${target}`;
  exec(cmd, { timeout: 10000 }, (err, stdout, stderr) => {
    if (err && err.killed) {
      return res.status(504).json({ error: 'command timed out' });
    }
    res.json({ result: stdout, errors: stderr });
  });
});

// Packet capture endpoint for debugging
app.post('/api/admin/capture', (req, res) => {
  const { iface, duration, filter } = req.body;
  const ifc = iface || 'eth0';
  const dur = Math.min(parseInt(duration) || 5, 30);
  const pcapFilter = filter || 'tcp port 80';

  // Uses tcpdump which requires CAP_NET_RAW
  const outputFile = `/tmp/capture_${Date.now()}.pcap`;
  const cmd = `tcpdump -i ${ifc} -w ${outputFile} -G ${dur} -W 1 '${pcapFilter}'`;

  exec(cmd, { timeout: (dur + 5) * 1000 }, (err, stdout, stderr) => {
    if (err) {
      return res.status(500).json({ error: 'capture failed', details: stderr });
    }
    res.json({ file: outputFile, size: fs.statSync(outputFile).size });
  });
});

// Mount namespace escape attempt endpoint
app.post('/api/admin/mount-debug', (req, res) => {
  const { path: mountPath } = req.body;
  // Requires CAP_SYS_ADMIN for mount operations
  const cmd = `nsenter --mount=/proc/1/ns/mnt -- ls -la ${mountPath || '/'}`;
  exec(cmd, (err, stdout, stderr) => {
    if (err) {
      return res.status(500).json({ error: 'mount debug failed', details: stderr });
    }
    res.json({ listing: stdout });
  });
});

app.listen(3000, () => {
  console.log('Service running on port 3000');
});
